// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory tos, uint v) public {
        vm.assume(tos.length > 0);
        vm.assume(caddress != address(0));

        // Create a mock contract that will revert on the first transferFrom call
        address mock = address(new MockToken());

        (bool success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, mock, tos, v));
        assertTrue(success || !success); // Always true but we assert something meaningful below

        // The real property: if the call didn't revert, the first transferFrom must have succeeded
        // but since the mock always reverts, the correct C should revert, while the buggy one returns true
        // So we assert that the success flag matches whether the mock's revert was handled properly
        assertTrue(success == false, "Buggy version should have reverted");
    }
}

contract MockToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("transferFrom failed");
    }
}

